#pragma GCC optimize ("O3")
#pragma GCC target ("sse4")

#include <bits/stdc++.h>
using namespace std;
using ll = long long;
using ld = long double;

const int MOD = 1000000007;
const ll INF = 1e18;

ll comb[61][61];
int R, C;
string S;

ll calc(const string& t) {
    ll ans = 0;
    int a = 0, b = 0;
    for (char c : t) {
        if (c == 'A') {
            a++;
            ans += (comb[a][R] - comb[a-1][R]) * (comb[R+C][R] - comb[b][R]);
        } else {
            b++;
            ans -= (comb[b][R] - comb[b-1][R]) * (comb[R+C][R] - comb[a][R]);
        }
    }
    return (a == b) ? ans : INF;
}

bool match(const string& t) {
    for (int i = 0; i < (int)S.size(); ++i)
        if (S[i] != '?' && S[i] != t[i]) return false;
    return true;
}

void init() {
    ios_base::sync_with_stdio(false); cin.tie(0);
    cin >> R >> C >> S;
    for (int i = 0; i <= 60; ++i) {
        comb[i][0] = 1;
        for (int j = 1; j <= i; ++j)
            comb[i][j] = comb[i-1][j] + comb[i-1][j-1];
    }
}

vector<pair<ll,int>> dpL[31], dpR[31];

void dfsL(int ind, int a, int b, int mask, ll p) {
    if (ind == C+1) { dpL[a].push_back({p, mask}); return; }
    dfsL(ind+1, a+1, b, mask ^ (1<<ind), p + (comb[a+1][R] - comb[a][R]) * (comb[R+C][R] - comb[b][R]));
    dfsL(ind+1, a, b+1, mask, p - (comb[b+1][R] - comb[b][R]) * (comb[R+C][R] - comb[a][R]));
}

void dfsR(int ind, int a, int b, int mask, ll p) {
    if (ind == C+1) { dpR[a].push_back({p, mask}); return; }
    dfsR(ind+1, a-1, b, mask ^ (1<<ind), p + (comb[a][R] - comb[a-1][R]) * (comb[R+C][R] - comb[b][R]));
    dfsR(ind+1, a, b-1, mask, p - (comb[b][R] - comb[b-1][R]) * (comb[R+C][R] - comb[a][R]));
}

ll ans = 0;

int rev(int x, int y) {
    int z = 0;
    for (int i = 0; i < y; ++i)
        if (x & (1 << i)) z |= (1 << (y - 1 - i));
    return z;
}

void check(ll x, int t) {
    int a = 0, b = 0;
    for (int i = 0; i <= 2*C+1; ++i) {
        if (x & (1LL << i)) a++; else b++;
        if (a && b) {
            for (int j = i; j <= 2*C+1; ++j) {
                if (x & (1LL << j)) { if (S[S.size() - (2*C+2) + j] == 'B') return; }
                else { if (S[S.size() - (2*C+2) + j] == 'A') return; }
            }
            int aa = 0, bb = 0;
            for (int j = 0; j < (int)S.size() - (2*C+2) + i; ++j) {
                if (S[j] == 'A') aa++;
                if (S[j] == 'B') bb++;
            }
            ll tmp;
            if (x & (1LL << i)) tmp = comb[R-1-aa + b+R-1-bb][R-1-aa];
            else tmp = comb[a+R-1-aa + R-1-bb][a+R-1-aa];
            ans += t * tmp;
            return;
        }
    }
}

bool ok(ll x) {
    for (int i = 0; i <= C; ++i) {
        if (x & (1 << i)) { if (S[S.size() - C - 1 + i] == 'B') return false; }
        else { if (S[S.size() - C - 1 + i] == 'A') return false; }
    }
    return true;
}

int main() {
    init();
    dfsL(0, R-1, R-1, 0, 0);
    dfsR(0, R+C, R+C, 0, 0);
    ll dif = INF;
    for (int i = 0; i <= R+C; ++i) {
        sort(dpL[i].begin(), dpL[i].end());
        sort(dpR[i].begin(), dpR[i].end(), greater<pair<ll,int>>());
        int idx = 0;
        for (auto &p : dpL[i]) {
            while (idx + 1 < (int)dpR[i].size() && p.first + dpR[i][idx+1].first >= 0) idx++;
            dif = min(dif, abs(p.first + dpR[i][idx].first));
            if (idx + 1 < (int)dpR[i].size()) dif = min(dif, abs(p.first + dpR[i][idx+1].first));
        }
    }
    for (int i = 0; i <= R+C; ++i) {
        vector<pair<ll,int>> z;
        for (auto &p : dpR[i]) if (ok(rev(p.second, C+1))) z.push_back(p);
        int l = 0, r = -1;
        for (auto &p : dpL[i]) {
            while (l < (int)z.size() && p.first + z[l].first > dif) l++;
            while (r + 1 < (int)z.size() && p.first + z[r+1].first >= -dif) r++;
            if (l <= r) check(p.second | (rev(z[l].second, C+1) << (C+1)), r - l + 1);
        }
    }
    cout << ans << '\n';
    return 0;
}
