                while (r + 1 < z.size() && p.first + z.get(r+1).first >= -dif) r++;
                if (l <= r) check(p.second | ((long)rev(z.get(l).second, C+1) << (C+1)), r - l + 1);
            }
        }
        System.out.println(ans);
    }
}
